CREATE TABLE deliveries (
    id integer NOT NULL,
    parcel_id bigint NOT NULL,
    courier_id bigint REFERENCES drivers (id),
    attempted_at timestamptz NOT NULL,
    signature text
);

ALTER TABLE deliveries ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE deliveries ADD PRIMARY KEY (id);
ALTER TABLE deliveries
    ADD CONSTRAINT deliveries_parcel_id_fkey FOREIGN KEY (parcel_id) REFERENCES parcels (id);

/* Every scan and attempt, by month. */
CREATE TABLE delivery_events (
    delivery_id integer NOT NULL REFERENCES deliveries (id),
    recorded_at timestamptz NOT NULL DEFAULT now(),
    kind text NOT NULL,
    detail jsonb
) PARTITION BY RANGE (recorded_at);

CREATE TABLE delivery_events_2026 PARTITION OF delivery_events
    FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
